"""URL slugs for titles."""
import re
import unicodedata


def _base_slug(title):
    """Lower-case ASCII words joined by hyphens, without any length limit."""
    text = unicodedata.normalize("NFKD", title)
    text = "".join(ch for ch in text if not unicodedata.combining(ch)).lower()
    slug = re.sub(r"[^a-z0-9]+", "-", text).strip("-")
    return slug or "untitled"


def _check_max_length(max_length):
    if max_length is not None and max_length < 1:
        raise ValueError("max_length must be at least 1")


def _shorten(slug, max_length):
    """Keep the longest run of whole leading words that fits in max_length.

    If the first word alone does not fit, cut it to exactly max_length.
    """
    if len(slug) <= max_length:
        return slug
    words = slug.split("-")
    if len(words[0]) > max_length:
        return words[0][:max_length]
    result = words[0]
    for word in words[1:]:
        if len(result) + 1 + len(word) > max_length:
            break
        result += "-" + word
    return result


def slugify(title, max_length=None):
    """Return the URL slug for title, optionally at most max_length characters."""
    _check_max_length(max_length)
    slug = _base_slug(title)
    if max_length is None:
        return slug
    return _shorten(slug, max_length)


def unique_slug(title, taken, max_length=None):
    """Return a slug for title that is not in taken.

    taken is not modified. If the base slug is in use, the suffixes -2, -3, ...
    are tried in turn. With max_length, the whole result including the suffix
    is at most max_length characters, so the base is shortened for each suffix.
    """
    _check_max_length(max_length)
    candidate = slugify(title, max_length)
    if candidate not in taken:
        return candidate
    base = _base_slug(title)
    n = 2
    while True:
        suffix = "-{}".format(n)
        if max_length is None:
            candidate = base + suffix
        else:
            room = max_length - len(suffix)
            if room < 1:
                raise ValueError(
                    "max_length leaves no room for the base before suffix %s" % suffix
                )
            candidate = _shorten(base, room) + suffix
        if candidate not in taken:
            return candidate
        n += 1
